INSERT INTO `v1_764a0661d321bf022e858f0a9da8c23c06e6472816701ba3f4cc59fecb50f8e0` VALUES ("やったね、ぷうきち！\nこれならお兄ちゃんたちの\nお手本になれたよね！", 2, 2, "アヤネ", 24001, "2020/07/31 12:00:00", 0, 24, 401, 0, 10046, 0, 102301, "2030/12/17 14:59:59");
INSERT INTO `v1_764a0661d321bf022e858f0a9da8c23c06e6472816701ba3f4cc59fecb50f8e0` VALUES ("私たちの勝ちだね！\nぷうきちと一緒なら\nどんなボールでも\nホームランを打ってみせるよ！", 2, 1, "アヤネ", 24002, "2020/07/31 12:00:00", 0, 24, 402, 2.21, 10046, 0, 102301, "2030/12/17 14:59:59");
INSERT INTO `v1_764a0661d321bf022e858f0a9da8c23c06e6472816701ba3f4cc59fecb50f8e0` VALUES ("やったやったぁ！\nお兄ちゃん、見ててくれた？\n私、すっごくがんばったよ！", 2, 2, "アヤネ", 24003, "2020/07/31 12:00:00", 0, 24, 403, 0, 10046, 0, 102301, "2030/12/17 14:59:59");
INSERT INTO `v1_764a0661d321bf022e858f0a9da8c23c06e6472816701ba3f4cc59fecb50f8e0` VALUES ("特訓の成果が出たみたいだ！\nもっと練習を重ねて\nこの調子で上達していこう！", 1, 2, "アサヒ", 24004, "2020/07/31 12:00:00", 0, 24, 701, 1.99, 10046, 0, 192201, "2030/12/17 14:59:59");
INSERT INTO `v1_764a0661d321bf022e858f0a9da8c23c06e6472816701ba3f4cc59fecb50f8e0` VALUES ("よし、いい感じだ！\nキャプテンとしての仕事は\nきっちり果たせそうだよ", 2, 1, "アサヒ", 24005, "2020/07/31 12:00:00", 0, 24, 702, 2.21, 10046, 0, 192201, "2030/12/17 14:59:59");
INSERT INTO `v1_764a0661d321bf022e858f0a9da8c23c06e6472816701ba3f4cc59fecb50f8e0` VALUES ("試合に向けて\nいい感覚を掴めた気がするよ！\nこのまま一気に全国大会だ！", 1, 2, "アサヒ", 24006, "2020/07/31 12:00:00", 0, 24, 703, 3.33, 10046, 0, 192201, "2030/12/17 14:59:59");
INSERT INTO `v1_764a0661d321bf022e858f0a9da8c23c06e6472816701ba3f4cc59fecb50f8e0` VALUES ("このくらい余裕だ\nオレたちは全国大会を\n目指してるんだからな", 2, 2, "部員３", 24007, "2020/07/31 12:00:00", 0, 24, 801, 0, 10046, 0, 192301, "2030/12/17 14:59:59");
INSERT INTO `v1_764a0661d321bf022e858f0a9da8c23c06e6472816701ba3f4cc59fecb50f8e0` VALUES ("オレだって\nビーチベースボール選手だ\nどんな球だろうが\n全部スタンドまで飛ばしてやる", 2, 1, "部員３", 24008, "2020/07/31 12:00:00", 0, 24, 802, 2.68, 10046, 0, 192301, "2030/12/17 14:59:59");
INSERT INTO `v1_764a0661d321bf022e858f0a9da8c23c06e6472816701ba3f4cc59fecb50f8e0` VALUES ("いい感じだ\nこれなら試合でも活躍できそうだ\n大暴れしてやる！", 2, 2, "部員３", 24009, "2020/07/31 12:00:00", 0, 24, 803, 0, 10046, 0, 192301, "2030/12/17 14:59:59");
INSERT INTO `v1_764a0661d321bf022e858f0a9da8c23c06e6472816701ba3f4cc59fecb50f8e0` VALUES ("やった！", 1, 1, "", 24010, "2020/07/31 12:00:00", 0, 24, 501, 0, 10046, 0, 192501, "2030/12/17 14:59:59");
INSERT INTO `v1_764a0661d321bf022e858f0a9da8c23c06e6472816701ba3f4cc59fecb50f8e0` VALUES ("勝ったよ！", 1, 1, "", 24011, "2020/07/31 12:00:00", 0, 24, 502, 0, 10046, 0, 192501, "2030/12/17 14:59:59");
INSERT INTO `v1_764a0661d321bf022e858f0a9da8c23c06e6472816701ba3f4cc59fecb50f8e0` VALUES ("いい調子！", 1, 1, "", 24012, "2020/07/31 12:00:00", 0, 24, 503, 0, 10046, 0, 192501, "2030/12/17 14:59:59");
INSERT INTO `v1_764a0661d321bf022e858f0a9da8c23c06e6472816701ba3f4cc59fecb50f8e0` VALUES ("あら～…もしかして\n勝っちゃったのかしら？\nみんなの練習を見ていたから\nかもしれないわね", 2, 6, "ミサト", 24013, "2020/07/31 12:00:00", 0, 24, 111, 5.33, 10046, 0, 113501, "2030/12/17 14:59:59");
INSERT INTO `v1_764a0661d321bf022e858f0a9da8c23c06e6472816701ba3f4cc59fecb50f8e0` VALUES ("みんなの力になりたくて\n先生も頑張ってみました～！\nうまく投げられたみたいで\nよかったわ～！", 2, 1, "ミサト", 24014, "2020/07/31 12:00:00", 0, 24, 112, 6.85, 10046, 0, 113501, "2030/12/17 14:59:59");
INSERT INTO `v1_764a0661d321bf022e858f0a9da8c23c06e6472816701ba3f4cc59fecb50f8e0` VALUES ("練習お疲れさま～！\n先生も協力できて\nとってもうれしいわ～♪\n次も頑張りましょうね～！", 2, 1, "ミサト", 24015, "2020/07/31 12:00:00", 0, 24, 113, 3, 10046, 0, 113501, "2030/12/17 14:59:59");
INSERT INTO `v1_764a0661d321bf022e858f0a9da8c23c06e6472816701ba3f4cc59fecb50f8e0` VALUES ("まだ練習が足りねえみてえだな\nこれっぽっちも本気で\n投げてねえっつーの\nもう一回やんぞ！", 2, 1, "ダイチ", 24016, "2020/07/31 12:00:00", 0, 24, 611, 6.11, 10046, 0, 192401, "2030/12/17 14:59:59");
INSERT INTO `v1_764a0661d321bf022e858f0a9da8c23c06e6472816701ba3f4cc59fecb50f8e0` VALUES ("ふん、当然の結果だな\n俺の球は、誰にも打てねえよ！\nまたやりてえっつーなら\nとことん付き合ってやるぜ！", 2, 1, "ダイチ", 24017, "2020/07/31 12:00:00", 0, 24, 612, 6.75, 10046, 0, 192401, "2030/12/17 14:59:59");
INSERT INTO `v1_764a0661d321bf022e858f0a9da8c23c06e6472816701ba3f4cc59fecb50f8e0` VALUES ("おっしゃあ！\nこの勢いで全国に行ってやるぜ！\n全員三振で仕留めてやる！", 2, 2, "ダイチ", 24018, "2020/07/31 12:00:00", 0, 24, 613, 0, 10046, 0, 192401, "2030/12/17 14:59:59");
INSERT INTO `v1_764a0661d321bf022e858f0a9da8c23c06e6472816701ba3f4cc59fecb50f8e0` VALUES ("きらーん☆\nハツネちゃんの大勝利なのだ～！\nみんながもっと上達できるように\n私もまだまだ頑張るからね！", 1, 2, "ハツネ", 24019, "2020/07/31 12:00:00", 0, 24, 211, 4.52, 10046, 0, 113401, "2030/12/17 14:59:59");
INSERT INTO `v1_764a0661d321bf022e858f0a9da8c23c06e6472816701ba3f4cc59fecb50f8e0` VALUES ("やったあ！　私の勝ちだね！\nチアリーダーもピッチャーも\nハツネちゃんに任せてよ！", 1, 2, "ハツネ", 24020, "2020/07/31 12:00:00", 0, 24, 212, 3.89, 10046, 0, 113401, "2030/12/17 14:59:59");
INSERT INTO `v1_764a0661d321bf022e858f0a9da8c23c06e6472816701ba3f4cc59fecb50f8e0` VALUES ("よお～し、この調子でもっと\n頑張ろう…と思ったけど\n超能力を使ったから…\n眠くなってきちゃった…すやぁ…", 2, 1, "ハツネ", 24021, "2020/07/31 12:00:00", 0, 24, 213, 13.49, 10046, 0, 113401, "2030/12/17 14:59:59");
INSERT INTO `v1_764a0661d321bf022e858f0a9da8c23c06e6472816701ba3f4cc59fecb50f8e0` VALUES ("いい勝負だったぜ！\nたぎっちまって\nつい本気で投げちまったよ", 2, 1, "カヤ", 24022, "2020/07/31 12:00:00", 0, 24, 311, 3.17, 10046, 0, 106501, "2030/12/17 14:59:59");
INSERT INTO `v1_764a0661d321bf022e858f0a9da8c23c06e6472816701ba3f4cc59fecb50f8e0` VALUES ("どうだ？\nオレ様のボールは熱かっただろ！\nま、でもおまえらの根性も\nなかなかのもんだったぜ", 2, 1, "カヤ", 24023, "2020/07/31 12:00:00", 0, 24, 312, 4.42, 10046, 0, 106501, "2030/12/17 14:59:59");
INSERT INTO `v1_764a0661d321bf022e858f0a9da8c23c06e6472816701ba3f4cc59fecb50f8e0` VALUES ("なんだよ、そんなもんか？\nこっちはまだまだ投げたりねえ\nもっと勝負しようぜ！", 1, 6, "カヤ", 24024, "2020/07/31 12:00:00", 0, 24, 313, 2.89, 10046, 0, 106501, "2030/12/17 14:59:59");
INSERT INTO `v1_764a0661d321bf022e858f0a9da8c23c06e6472816701ba3f4cc59fecb50f8e0` VALUES ("あとちょっとだったのに～！\n次こそぷうきちと一緒に\n勝ってみせるからね！", 3, 4, "アヤネ", 24025, "2020/07/31 12:00:00", 0, 24, 421, 3.71, 10046, 0, 102301, "2030/12/17 14:59:59");
INSERT INTO `v1_764a0661d321bf022e858f0a9da8c23c06e6472816701ba3f4cc59fecb50f8e0` VALUES ("いい勝負だったね！\nでも、やっぱり悔しいな…\nもっと練習して\n今度は絶対に俺が勝つから！", 1, 2, "アサヒ", 24026, "2020/07/31 12:00:00", 0, 24, 721, 5.1, 10046, 0, 192201, "2030/12/17 14:59:59");
INSERT INTO `v1_764a0661d321bf022e858f0a9da8c23c06e6472816701ba3f4cc59fecb50f8e0` VALUES ("ちっ…あと一歩足りなかったか\n次こそは絶対に勝つから\nそのつもりでいろ", 3, 1, "部員３", 24027, "2020/07/31 12:00:00", 0, 24, 821, 4.34, 10046, 0, 192301, "2030/12/17 14:59:59");
INSERT INTO `v1_764a0661d321bf022e858f0a9da8c23c06e6472816701ba3f4cc59fecb50f8e0` VALUES ("いい勝負だったよ\nまたやろうね", 1, 1, "", 24028, "2020/07/31 12:00:00", 0, 24, 521, 0, 10046, 0, 192501, "2030/12/17 14:59:59");
INSERT INTO `v1_764a0661d321bf022e858f0a9da8c23c06e6472816701ba3f4cc59fecb50f8e0` VALUES ("とってもよくできました～♪\n頑張ってくれて先生うれしいわ\nこれからも試合に向けて\n練習していきましょうね～", 2, 1, "ミサト", 24029, "2020/07/31 12:00:00", 0, 24, 101, 5.62, 10046, -360, 113501, "2030/12/17 14:59:59");
INSERT INTO `v1_764a0661d321bf022e858f0a9da8c23c06e6472816701ba3f4cc59fecb50f8e0` VALUES ("頑張った成果ね～！\nこのまま練習を続ければ\nもっとすごい成績を残せそうよ\n期待してますからね～！", 2, 1, "ミサト", 24030, "2020/07/31 12:00:00", 0, 24, 102, 9.58, 10046, -360, 113501, "2030/12/17 14:59:59");
INSERT INTO `v1_764a0661d321bf022e858f0a9da8c23c06e6472816701ba3f4cc59fecb50f8e0` VALUES ("いい子、いい子～♪\n頑張り屋さんのあなたを\nたっくさん褒めてあげますからね", 2, 2, "ミサト", 24031, "2020/07/31 12:00:00", 0, 24, 103, 0, 10046, -360, 113501, "2030/12/17 14:59:59");
INSERT INTO `v1_764a0661d321bf022e858f0a9da8c23c06e6472816701ba3f4cc59fecb50f8e0` VALUES ("夢に向けて、一歩前進できたわね\nこの調子で、夢を叶えましょう\n目指せ、全国大会～！", 1, 2, "ミサト", 24032, "2020/07/31 12:00:00", 0, 24, 104, 9.13, 10046, -360, 113501, "2030/12/17 14:59:59");
INSERT INTO `v1_764a0661d321bf022e858f0a9da8c23c06e6472816701ba3f4cc59fecb50f8e0` VALUES ("絶好調ね～♪\nきっと試合でも大活躍\n間違いなしだわ\n楽しみにしていますからね～！", 2, 1, "ミサト", 24033, "2020/07/31 12:00:00", 0, 24, 105, 8.27, 10046, -360, 113501, "2030/12/17 14:59:59");
